export enum Role {
  USER = 'user',
  MODEL = 'model'
}

export interface Message {
  id: string;
  role: Role;
  content: string;
  isStreaming?: boolean;
  timestamp: number;
}

export interface ChatState {
  messages: Message[];
  isLoading: boolean;
  error: string | null;
}

import { GoogleGenAI, GenerateContentResponse, Chat } from "@google/genai";
import { Message, Role } from "../types";
import { IBRAHIM_SYSTEM_INSTRUCTION } from "../constants";

// Initialize the Gemini Client
// CRITICAL: process.env.API_KEY is automatically injected by the environment.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const MODEL_NAME = 'gemini-2.5-flash';

/**
 * Creates a chat session and sends a message, returning a stream of responses.
 */
export const streamChatResponse = async (
  history: Message[],
  userMessage: string,
  onChunk: (text: string) => void
): Promise<void> => {
  try {
    // Transform application history to Gemini Chat history format
    // We filter out any messages that might be in a temporary "loading" or "streaming" state if necessary
    // But generally, the history passed here should be confirmed messages.
    const chatHistory = history.map((msg) => ({
      role: msg.role === Role.USER ? 'user' : 'model',
      parts: [{ text: msg.content }],
    }));

    const chat: Chat = ai.chats.create({
      model: MODEL_NAME,
      history: chatHistory,
      config: {
        systemInstruction: IBRAHIM_SYSTEM_INSTRUCTION,
        temperature: 0.7, // Balanced creativity and accuracy
      },
    });

    const result = await chat.sendMessageStream({ message: userMessage });

    for await (const chunk of result) {
        const c = chunk as GenerateContentResponse;
        if (c.text) {
            onChunk(c.text);
        }
    }
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

import React from 'react';
import ReactMarkdown from 'react-markdown';
import { Role } from '../types';

interface MarkdownRendererProps {
  content: string;
  role: Role;
}

const MarkdownRenderer: React.FC<MarkdownRendererProps> = ({ content, role }) => {
  return (
    <div className={`markdown-content text-sm md:text-base ${role === Role.USER ? 'text-white' : 'text-slate-800'}`}>
      <ReactMarkdown
        components={{
          a: ({ node, ...props }) => (
            <a 
              {...props} 
              target="_blank" 
              rel="noopener noreferrer" 
              className={`underline ${role === Role.USER ? 'text-white hover:text-blue-100' : 'text-blue-600 hover:text-blue-800'}`}
            />
          ),
          code: ({ node, className, children, ...props }) => {
            const match = /language-(\w+)/.exec(className || '');
            const isInline = !match;
            return isInline ? (
               <code className={`${role === Role.USER ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-800'} rounded px-1 py-0.5`} {...props}>
                {children}
               </code>
            ) : (
                <div className="my-2 overflow-hidden rounded-md">
                     <div className="bg-slate-800 text-xs text-slate-400 px-3 py-1 flex justify-between items-center">
                        <span>{match?.[1] || 'Code'}</span>
                    </div>
                    <pre className="bg-slate-900 !p-3 !m-0 overflow-x-auto text-slate-100">
                        <code className={className} {...props}>
                            {children}
                        </code>
                    </pre>
                </div>
            )
          },
        }}
      >
        {content}
      </ReactMarkdown>
    </div>
  );
};

export default MarkdownRenderer;

