import React, { useState, useRef, useEffect } from 'react';
import { Send, StopCircle } from 'lucide-react';

interface InputAreaProps {
  onSend: (message: string) => void;
  isLoading: boolean;
}

const InputArea: React.FC<InputAreaProps> = ({ onSend, isLoading }) => {
  const [input, setInput] = useState('');
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const handleSubmit = (e?: React.FormEvent) => {
    e?.preventDefault();
    if (input.trim() && !isLoading) {
      onSend(input.trim());
      setInput('');
      if (textareaRef.current) {
        textareaRef.current.style.height = 'auto';
      }
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit();
    }
  };

  const handleInput = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setInput(e.target.value);
    // Auto-grow textarea
    e.target.style.height = 'auto';
    e.target.style.height = `${Math.min(e.target.scrollHeight, 200)}px`;
  };

  // Focus input on mount and after loading finishes
  useEffect(() => {
    if (!isLoading) {
        textareaRef.current?.focus();
    }
  }, [isLoading]);

  return (
    <div className="flex-none bg-white border-t border-slate-200 p-4">
      <div className="max-w-4xl mx-auto">
        <form 
            onSubmit={handleSubmit} 
            className={`relative flex items-end gap-2 bg-slate-50 border border-slate-300 rounded-2xl p-2 focus-within:ring-2 focus-within:ring-brand-200 focus-within:border-brand-400 transition-all shadow-inner ${isLoading ? 'opacity-80' : ''}`}
        >
          <textarea
            ref={textareaRef}
            rows={1}
            value={input}
            onChange={handleInput}
            onKeyDown={handleKeyDown}
            placeholder={isLoading ? "Ibrahim's AI is replying..." : "Ask Ibrahim's AI anything..."}
            className="w-full bg-transparent border-none focus:ring-0 text-slate-800 placeholder-slate-400 resize-none py-3 px-3 min-h-[48px] max-h-[200px]"
            disabled={isLoading}
          />
          <button
            type="submit"
            disabled={!input.trim() || isLoading}
            className={`p-3 rounded-xl flex-none transition-all duration-200 mb-0.5 ${
              !input.trim() || isLoading
                ? 'bg-slate-200 text-slate-400 cursor-not-allowed'
                : 'bg-brand-600 text-white hover:bg-brand-700 hover:shadow-md'
            }`}
          >
            {isLoading ? <StopCircle size={20} /> : <Send size={20} />}
          </button>
        </form>
        <div className="text-center mt-2">
            <p className="text-[10px] text-slate-400">
                AI can make mistakes. Please verify important information.
            </p>
        </div>
      </div>
    </div>
  );
};

export default InputArea;

import React, { useState, useCallback } from 'react';
import Header from './components/Header';
import ChatInterface from './components/ChatInterface';
import InputArea from './components/InputArea';
import { Message, Role } from './types';
import { streamChatResponse } from './services/geminiService';
import { v4 as uuidv4 } from 'uuid';

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  const handleSendMessage = useCallback(async (content: string) => {
    // 1. Add User Message
    const userMessage: Message = {
      id: uuidv4(),
      role: Role.USER,
      content,
      timestamp: Date.now(),
    };

    setMessages((prev) => [...prev, userMessage]);
    setIsLoading(true);

    try {
      // 2. Prepare Placeholder for AI Message
      const aiMessageId = uuidv4();
      const initialAiMessage: Message = {
        id: aiMessageId,
        role: Role.MODEL,
        content: '',
        isStreaming: true,
        timestamp: Date.now(),
      };

      setMessages((prev) => [...prev, initialAiMessage]);

      // 3. Stream Response
      let fullContent = '';

      // We pass the messages *before* the current user message + the current user message
      // But for the history passed to Gemini, we usually want the confirmed history.
      // `messages` state hasn't updated in this closure yet if we used `messages`, but we have functional updates.
      // However, for simplicity and correctness, we can just pass the current history we know of.
      // NOTE: We should filter out the empty AI placeholder we just added for the history call.

      await streamChatResponse(
        [...messages, userMessage], // Include the new user message in context
        content,
        (chunkText) => {
          fullContent += chunkText;
          setMessages((prev) => 
            prev.map((msg) => 
              msg.id === aiMessageId 
                ? { ...msg, content: fullContent } 
                : msg
            )
          );
        }
      );

      // 4. Finalize
      setMessages((prev) => 
        prev.map((msg) => 
          msg.id === aiMessageId 
            ? { ...msg, isStreaming: false } 
            : msg
        )
      );

    } catch (error) {
      console.error("Error sending message:", error);
      // Add error message to chat
       const errorMessage: Message = {
        id: uuidv4(),
        role: Role.MODEL,
        content: "I apologize, but I encountered a connection error. Please try asking again.",
        timestamp: Date.now(),
      };
      setMessages(prev => {
          // Remove the empty streaming message if it exists and failed
          const filtered = prev.filter(m => !m.isStreaming);
          return [...filtered, errorMessage];
      });
    } finally {
      setIsLoading(false);
    }
  }, [messages]);

  return (
    <div className="flex flex-col h-screen bg-slate-50 text-slate-900 font-sans">
      <Header />
      <main className="flex-1 flex flex-col min-h-0 relative">
        <ChatInterface messages={messages} isLoading={isLoading} />
        <InputArea onSend={handleSendMessage} isLoading={isLoading} />
      </main>
    </div>
  );
};

export default App;

