import React, { useState, useCallback } from 'react';
import Header from './components/Header';
import ChatInterface from './components/ChatInterface';
import InputArea from './components/InputArea';
import { Message, Role, Attachment } from './types';
import { streamChatResponse } from './services/geminiService';
import { v4 as uuidv4 } from 'uuid';

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  const handleSendMessage = useCallback(async (content: string, attachments: Attachment[]) => {
    const userMessage: Message = {
      id: uuidv4(),
      role: Role.USER,
      content,
      attachments,
      timestamp: Date.now(),
    };

    setMessages((prev) => [...prev, userMessage]);
    setIsLoading(true);

    try {
      const aiMessageId = uuidv4();
      const initialAiMessage: Message = {
        id: aiMessageId,
        role: Role.MODEL,
        content: '',
        isStreaming: true,
        timestamp: Date.now(),
      };

      setMessages((prev) => [...prev, initialAiMessage]);

      let fullContent = '';

      await streamChatResponse(
        messages, 
        content,
        attachments,
        (chunkText) => {
          fullContent += chunkText;
          setMessages((prev) => 
            prev.map((msg) => 
              msg.id === aiMessageId 
                ? { ...msg, content: fullContent } 
                : msg
            )
          );
        }
      );

      setMessages((prev) => 
        prev.map((msg) => 
          msg.id === aiMessageId 
            ? { ...msg, isStreaming: false } 
            : msg
        )
      );

    } catch (error) {
      console.error("Error sending message:", error);
       const errorMessage: Message = {
        id: uuidv4(),
        role: Role.MODEL,
        content: "I apologize, but I encountered a connection error while trying to process your request. Please try again.",
        timestamp: Date.now(),
      };
      setMessages(prev => [...prev.filter(m => !m.isStreaming), errorMessage]);
    } finally {
      setIsLoading(false);
    }
  }, [messages]);

  return (
    <div className="flex flex-col h-screen bg-slate-50 text-slate-900 font-sans">
      <Header />
      <main className="flex-1 flex flex-col min-h-0 relative">
        <ChatInterface messages={messages} isLoading={isLoading} />
        <InputArea onSend={handleSendMessage} isLoading={isLoading} />
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Send, StopCircle, Image as ImageIcon, Mic, X, Music } from 'lucide-react';
import { Attachment } from '../types';

interface InputAreaProps {
  onSend: (message: string, attachments: Attachment[]) => void;
  isLoading: boolean;
}

const InputArea: React.FC<InputAreaProps> = ({ onSend, isLoading }) => {
  const [input, setInput] = useState('');
  const [attachments, setAttachments] = useState<Attachment[]>([]);
  const [isRecording, setIsRecording] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSubmit = (e?: React.FormEvent) => {
    e?.preventDefault();
    if ((input.trim() || attachments.length > 0) && !isLoading) {
      onSend(input.trim(), attachments);
      setInput('');
      setAttachments([]);
      if (textareaRef.current) textareaRef.current.style.height = 'auto';
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit();
    }
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];

      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) audioChunksRef.current.push(event.data);
      };

      mediaRecorder.onstop = async () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
        const reader = new FileReader();
        reader.readAsDataURL(audioBlob);
        reader.onloadend = () => {
          const base64data = reader.result as string;
          const base64Content = base64data.split(',')[1];
          setAttachments(prev => [...prev, {
            type: 'audio',
            data: base64Content,
            mimeType: 'audio/webm',
            url: URL.createObjectURL(audioBlob)
          }]);
        };
        stream.getTracks().forEach(track => track.stop());
      };

      mediaRecorder.start();
      setIsRecording(true);
    } catch (err) {
      console.error("Microphone access denied:", err);
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;

    // Fix: Explicitly type 'file' as File to avoid 'unknown' type errors
    Array.from(files).forEach((file: File) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64data = reader.result as string;
        const base64Content = base64data.split(',')[1];
        setAttachments(prev => [...prev, {
          type: 'image',
          data: base64Content,
          mimeType: file.type,
          url: URL.createObjectURL(file)
        }]);
      };
      reader.readAsDataURL(file);
    });
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const removeAttachment = (index: number) => {
    setAttachments(prev => prev.filter((_, i) => i !== index));
  };

  return (
    <div className="flex-none bg-white border-t border-slate-200 p-4">
      <div className="max-w-4xl mx-auto">
        {attachments.length > 0 && (
          <div className="flex flex-wrap gap-2 mb-3">
            {attachments.map((att, i) => (
              <div key={i} className="relative group animate-fade-in">
                {att.type === 'image' ? (
                  <img src={att.url} className="w-16 h-16 object-cover rounded-lg border border-slate-200 shadow-sm" alt="Preview" />
                ) : (
                  <div className="w-16 h-16 flex flex-col items-center justify-center bg-brand-50 rounded-lg border border-brand-200">
                    <Music className="text-brand-500" size={20} />
                    <span className="text-[8px] mt-1 font-bold text-brand-600">AUDIO</span>
                  </div>
                )}
                <button 
                  onClick={() => removeAttachment(i)}
                  className="absolute -top-2 -right-2 bg-slate-800 text-white rounded-full p-1 shadow-md opacity-0 group-hover:opacity-100 transition-opacity"
                >
                  <X size={10} />
                </button>
              </div>
            ))}
          </div>
        )}

        <form onSubmit={handleSubmit} className="flex items-end gap-2">
          <div className="flex-1 relative flex flex-col bg-slate-50 border border-slate-300 rounded-2xl p-1.5 focus-within:ring-2 focus-within:ring-brand-200 focus-within:border-brand-400 transition-all">
            <textarea
              ref={textareaRef}
              rows={1}
              value={input}
              onChange={(e) => {
                setInput(e.target.value);
                e.target.style.height = 'auto';
                e.target.style.height = `${Math.min(e.target.scrollHeight, 200)}px`;
              }}
              onKeyDown={handleKeyDown}
              placeholder={isRecording ? "Listening..." : "Ask Ibrahim's AI anything..."}
              className="w-full bg-transparent border-none focus:ring-0 text-slate-800 placeholder-slate-400 resize-none py-2 px-3 min-h-[44px]"
              disabled={isLoading || isRecording}
            />
            <div className="flex items-center justify-between px-2 pb-1">
              <div className="flex gap-1">
                <button
                  type="button"
                  onClick={() => fileInputRef.current?.click()}
                  className="p-1.5 text-slate-500 hover:text-brand-600 hover:bg-brand-50 rounded-lg transition-colors"
                  title="Upload image"
                >
                  <ImageIcon size={18} />
                </button>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={handleImageUpload} />

                <button
                  type="button"
                  onMouseDown={startRecording}
                  onMouseUp={stopRecording}
                  onTouchStart={startRecording}
                  onTouchEnd={stopRecording}
                  className={`p-1.5 rounded-lg transition-all ${isRecording ? 'text-red-500 bg-red-50 animate-pulse' : 'text-slate-500 hover:text-brand-600 hover:bg-brand-50'}`}
                  title="Hold to record voice"
                >
                  <Mic size={18} />
                </button>
              </div>
              <div className="text-[10px] text-slate-400 italic">
                {isRecording && "Recording..."}
              </div>
            </div>
          </div>
          <button
            type="submit"
            disabled={(!input.trim() && attachments.length === 0) || isLoading}
            className={`p-3 rounded-xl flex-none transition-all duration-200 ${
              (!input.trim() && attachments.length === 0) || isLoading
                ? 'bg-slate-200 text-slate-400'
                : 'bg-brand-600 text-white hover:bg-brand-700 hover:shadow-md'
            }`}
          >
            {isLoading ? <StopCircle size={20} className="animate-spin-slow" /> : <Send size={20} />}
          </button>
        </form>
      </div>
    </div>
  );
};

