import { GoogleGenAI, GenerateContentResponse, Chat } from "@google/genai";
import { Message, Role, Attachment } from "../types";
import { IBRAHIM_SYSTEM_INSTRUCTION } from "../constants";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
// Use 'gemini-3-flash-preview' for general text and multimodal chat tasks
const MODEL_NAME = 'gemini-3-flash-preview';

export const streamChatResponse = async (
  history: Message[],
  userMessage: string,
  attachments: Attachment[],
  onChunk: (text: string) => void
): Promise<void> => {
  try {
    const chatHistory = history.map((msg) => ({
      role: msg.role === Role.USER ? 'user' : 'model',
      parts: [
        { text: msg.content },
        ...(msg.attachments?.map(att => ({
          inlineData: {
            data: att.data,
            mimeType: att.mimeType
          }
        })) || [])
      ],
    }));

    const currentDateTime = new Date().toLocaleString('en-US', {
      dateStyle: 'full',
      timeStyle: 'medium',
    });

    const systemInstructionWithContext = `${IBRAHIM_SYSTEM_INSTRUCTION}\n\n[System Context]\nCurrent Date and Time: ${currentDateTime}\n`;

    const chat: Chat = ai.chats.create({
      model: MODEL_NAME,
      history: chatHistory,
      config: {
        systemInstruction: systemInstructionWithContext,
        temperature: 0.7,
      },
    });

    // Construct the current message parts including text and any attachments
    const currentParts = [
      { text: userMessage },
      ...attachments.map(att => ({
        inlineData: {
          data: att.data,
          mimeType: att.mimeType
        }
      }))
    ];

    const result = await chat.sendMessageStream({ 
      message: { parts: currentParts }
    });

    for await (const chunk of result) {
      const c = chunk as GenerateContentResponse;
      // Access the text property directly (not as a method) as per SDK rules
      if (c.text) {
        onChunk(c.text);
      }
    }
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

import { GoogleGenAI, GenerateContentResponse, Chat, Modality } from "@google/genai";
import { Message, Role, Attachment } from "../types";
import { IBRAHIM_SYSTEM_INSTRUCTION } from "../constants";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Using gemini-2.5-flash-image as the core model because it can both 
// understand multimodal input and GENERATE images.
const CORE_MODEL = 'gemini-2.5-flash-image';
const TTS_MODEL = 'gemini-2.5-flash-preview-tts';

export const streamChatResponse = async (
  history: Message[],
  userMessage: string,
  attachments: Attachment[],
  onChunk: (text: string, imageUrl?: string) => void
): Promise<void> => {
  try {
    const chatHistory = history.map((msg) => ({
      role: msg.role === Role.USER ? 'user' : 'model',
      parts: [
        { text: msg.content },
        ...(msg.attachments?.map(att => ({
          inlineData: {
            data: att.data,
            mimeType: att.mimeType
          }
        })) || [])
      ],
    }));

    const currentDateTime = new Date().toLocaleString('en-US', {
      dateStyle: 'full',
      timeStyle: 'medium',
    });

    const systemInstructionWithContext = `${IBRAHIM_SYSTEM_INSTRUCTION}

[Capabilities Update]
- You can GENERATE images. If the user asks you to "draw", "create an image", or "show me", use your internal image generation capability.
- You are aware of current time: ${currentDateTime}
`;

    const chat: Chat = ai.chats.create({
      model: CORE_MODEL,
      history: chatHistory,
      config: {
        systemInstruction: systemInstructionWithContext,
        temperature: 0.7,
      },
    });

    const currentParts = [
      { text: userMessage },
      ...attachments.map(att => ({
        inlineData: {
          data: att.data,
          mimeType: att.mimeType
        }
      }))
    ];

    const result = await chat.sendMessageStream({ 
      message: { parts: currentParts }
    });

    for await (const chunk of result) {
      const c = chunk as GenerateContentResponse;

      // Iterate through parts to find text or images
      if (c.candidates?.[0]?.content?.parts) {
        for (const part of c.candidates[0].content.parts) {
          if (part.text) {
            onChunk(part.text);
          }
          if (part.inlineData && part.inlineData.mimeType.startsWith('image/')) {
            const imageUrl = `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
            onChunk("", imageUrl);
          }
        }
      }
    }
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

/**
 * Converts text to speech using Gemini TTS model
 */
export const generateSpeech = async (text: string): Promise<AudioBuffer> => {
  const response = await ai.models.generateContent({
    model: TTS_MODEL,
    contents: [{ parts: [{ text: `Speak this calmly and helpfully: ${text}` }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName: 'Kore' }, // Professional and calm
        },
      },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64Audio) throw new Error("No audio data returned");

  const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
  const audioData = decodeBase64(base64Audio);
  return await decodeAudioData(audioData, audioContext, 24000, 1);
};

// --- Audio Utilities ---

function decodeBase64(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState } from 'react';
import { Message, Role } from '../types';
import { Bot, User, Music, Volume2, Loader2 } from 'lucide-react';
