        id: aiMessageId,
        role: Role.MODEL,
        content: '',
        attachments: [],
        isStreaming: true,
        timestamp: Date.now(),
      };

      setMessages((prev) => [...prev, initialAiMessage]);

      let fullContent = '';
      const seenImageUrls = new Set<string>();

      await streamChatResponse(
        messages, 
        content,
        attachments,
        (chunkText, imageUrl) => {
          setMessages((prev) => 
            prev.map((msg) => {
              if (msg.id === aiMessageId) {
                let updatedMsg = { ...msg };

                if (chunkText) {
                  fullContent += chunkText;
                  updatedMsg.content = fullContent;
                }

