                    {
                      type: 'image',
                      data: imageUrl,
                      mimeType: 'image/png'
                    }
                  ];
                }

                return updatedMsg;
              }
              return msg;
            })
          );
        }
      );

      setMessages((prev) => 
        prev.map((msg) => 
          msg.id === aiMessageId 
            ? { ...msg, isStreaming: false } 
            : msg
        )
      );

    } catch (error) {
      console.error("Error sending message:", error);
       const errorMessage: Message = {
        id: uuidv4(),
        role: Role.MODEL,
        content: "I apologize, but I encountered a connection error. Please check your network and try again.",
        timestamp: Date.now(),
      };
      setMessages(prev => [...prev.filter(m => !m.isStreaming), errorMessage]);
