          <span className="text-[10px] text-slate-400 mt-1.5 px-1 font-medium tracking-tight">
            {isUser ? 'YOU' : "IBRAHIM'S AI"} • {new Date(message.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
          </span>
        </div>
      </div>
    </div>
  );
};

