import React, { useState, useCallback } from 'react';
import Header from './components/Header';
import ChatInterface from './components/ChatInterface';
import InputArea from './components/InputArea';
import { Message, Role, Attachment, GroundingSource, MessageMood } from './types';
import { streamChatResponse } from './services/geminiService';
import { playAssistantVoice } from './services/audioService';
import { v4 as uuidv4 } from 'uuid';

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  const handleSendMessage = useCallback(async (content: string, attachments: Attachment[]) => {
    if (!content.trim() && attachments.length === 0) return;

    const hasAudioInput = attachments.some(a => a.type === 'audio');

    const userMessage: Message = {
      id: uuidv4(),
      role: Role.USER,
      content,
      attachments,
      timestamp: Date.now(),
    };

    setMessages((prev) => [...prev, userMessage]);
    setIsLoading(true);

    try {
      const aiMessageId = uuidv4();
      const initialAiMessage: Message = {
        id: aiMessageId,
        role: Role.MODEL,
        content: '',
        attachments: [],
        sources: [],
        isStreaming: true,
        timestamp: Date.now(),
      };

      setMessages((prev) => [...prev, initialAiMessage]);

      const seenImageUrls = new Set<string>();
      const seenSourceUrls = new Set<string>();
      let finalAiContent = '';

      await streamChatResponse(
        messages, 
        content,
        attachments,
        (text, imageUrl, sources, mood) => {
          setMessages((prev) => 
            prev.map((msg) => {
              if (msg.id === aiMessageId) {
                let updatedMsg = { ...msg };

                if (text) {
                  updatedMsg.content = text;
                  finalAiContent = text;
                }

                if (mood) {
                  updatedMsg.mood = mood;
                }

                if (imageUrl && !seenImageUrls.has(imageUrl)) {
                  seenImageUrls.add(imageUrl);
                  updatedMsg.attachments = [
                    ...(updatedMsg.attachments || []),
                    {
                      type: 'image',
                      data: imageUrl,
                      mimeType: 'image/png'
                    }
                  ];
                }

                if (sources) {
                  const newSources = [...(updatedMsg.sources || [])];
                  sources.forEach(src => {
                    if (!seenSourceUrls.has(src.url)) {
                      seenSourceUrls.add(src.url);
                      newSources.push(src);
                    }
                  });
                  updatedMsg.sources = newSources;
                }

                return updatedMsg;
              }
              return msg;
            })
          );
        }
      );

      setMessages((prev) => 
        prev.map((msg) => 
          msg.id === aiMessageId 
            ? { ...msg, isStreaming: false } 
            : msg
        )
      );

      // Auto-respond with voice if the user used audio input
      if (hasAudioInput && finalAiContent) {
        // We strip the first part of the response if it's too long for a single TTS call
        // or just play the whole thing if it's reasonable.
        playAssistantVoice(finalAiContent);
      }

    } catch (error: any) {
      console.error("Error sending message:", error);

      if (error?.message?.includes("Requested entity was not found.")) {
        const aistudio = (window as any).aistudio;
        if (aistudio) {
          aistudio.openSelectKey();
        }
      }

       const errorMessage: Message = {
        id: uuidv4(),
        role: Role.MODEL,
        content: "I apologize, but I encountered an error. If you are using global search, please ensure you have selected a valid paid API key via the settings button above.",
        timestamp: Date.now(),
      };
      setMessages(prev => [...prev.filter(m => !m.isStreaming), errorMessage]);
    } finally {
      setIsLoading(false);
    }
  }, [messages]);

  return (
    <div className="flex flex-col h-screen bg-slate-50 text-slate-900 font-sans">
      <Header />
      <main className="flex-1 flex flex-col min-h-0 relative">
        <ChatInterface messages={messages} isLoading={isLoading} />
        <InputArea onSend={handleSendMessage} isLoading={isLoading} />
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Message, Role, MessageMood } from '../types';
import { Bot, User, Music, Volume2, Loader2, ExternalLink, Globe, Heart, Zap, Shield, Brain, Sparkles, Smile, Search, HelpCircle, Square } from 'lucide-react';
import MarkdownRenderer from './MarkdownRenderer';
import { playAssistantVoice, stopAssistantVoice, isSpeaking } from '../services/audioService';

interface MessageBubbleProps {
  message: Message;
}

const moodConfig: Record<MessageMood, { icon: React.ReactNode, color: string, bg: string }> = {
  Thoughtful: { icon: <Brain size={10} />, color: 'text-purple-600', bg: 'bg-purple-50 border-purple-100' },
  Empathetic: { icon: <Heart size={10} />, color: 'text-rose-600', bg: 'bg-rose-50 border-rose-100' },
  Inspired: { icon: <Zap size={10} />, color: 'text-amber-600', bg: 'bg-amber-50 border-amber-100' },
  Calm: { icon: <Sparkles size={10} />, color: 'text-blue-600', bg: 'bg-blue-50 border-blue-100' },
  Cheerful: { icon: <Smile size={10} />, color: 'text-green-600', bg: 'bg-green-50 border-green-100' },
  Protective: { icon: <Shield size={10} />, color: 'text-orange-600', bg: 'bg-orange-50 border-orange-100' },
  Curious: { icon: <HelpCircle size={10} />, color: 'text-indigo-600', bg: 'bg-indigo-50 border-indigo-100' },
  Analytical: { icon: <Search size={10} />, color: 'text-slate-600', bg: 'bg-slate-50 border-slate-100' },
};

const MessageBubble: React.FC<MessageBubbleProps> = ({ message }) => {
  const isUser = message.role === Role.USER;
  const [localIsSpeaking, setLocalIsSpeaking] = useState(false);
  const mood = message.mood && moodConfig[message.mood] ? moodConfig[message.mood] : moodConfig['Calm'];

  // Sync local speaking state with global service
  useEffect(() => {
    const interval = setInterval(() => {
      // Very simple sync for UI feedback
      if (localIsSpeaking && !isSpeaking()) {
        setLocalIsSpeaking(false);
      }
    }, 100);
    return () => clearInterval(interval);
  }, [localIsSpeaking]);

  const handleToggleVoice = async () => {
    if (localIsSpeaking) {
      stopAssistantVoice();
      setLocalIsSpeaking(false);
    } else {
      if (!message.content) return;
      setLocalIsSpeaking(true);
      await playAssistantVoice(message.content);
      setLocalIsSpeaking(false);
    }
  };

  return (
    <div className={`flex w-full mb-6 animate-fade-in ${isUser ? 'justify-end' : 'justify-start'}`}>
      <div className={`flex max-w-[95%] md:max-w-[85%] gap-3 ${isUser ? 'flex-row-reverse' : 'flex-row'}`}>

        {/* Avatar */}
        <div className="flex-none pt-1">
          <div className={`w-9 h-9 rounded-xl flex items-center justify-center shadow-md transition-all duration-500 ${
            isUser ? 'bg-brand-600 text-white' : 'bg-white border border-slate-200 text-brand-600'
          } ${(!isUser && message.isStreaming) || localIsSpeaking ? 'animate-pulse ring-2 ring-brand-400' : ''}`}>
            {isUser ? <User size={18} /> : <Bot size={20} />}
          </div>
        </div>

        {/* Message Content */}
        <div className={`flex flex-col ${isUser ? 'items-end' : 'items-start'}`}>
          {/* AI Mood Badge */}
          {!isUser && message.mood && (
            <div className={`flex items-center gap-1 px-2 py-0.5 rounded-full border mb-1 transition-all animate-fade-in ${mood.bg} ${mood.color}`}>
              {mood.icon}
              <span className="text-[9px] font-bold uppercase tracking-wider">{message.mood}</span>
            </div>
          )}

          <div className={`relative px-5 py-4 rounded-2xl shadow-sm transition-all duration-200 ${
            isUser 
              ? 'bg-brand-600 text-white rounded-tr-sm' 
              : 'bg-white border border-slate-100 text-slate-800 rounded-tl-sm'
          }`}>
             {/* Attachments Rendering */}
             {message.attachments && message.attachments.length > 0 && (
               <div className="flex flex-col gap-3 mb-4">
                 {message.attachments.map((att, i) => (
                   att.type === 'image' ? (
                     <div key={i} className="relative group overflow-hidden rounded-xl border border-slate-200/50 bg-slate-50">
                        <img 
                          src={att.url || att.data} 
                          className="max-w-full max-h-[500px] object-contain mx-auto" 
                          alt="Generated or attached" 
                        />
                     </div>
                   ) : (
                     <div key={i} className={`flex items-center gap-3 px-4 py-3 rounded-xl border ${isUser ? 'bg-brand-700 border-brand-500' : 'bg-slate-50 border-slate-200'}`}>
                        <Music size={16} className={isUser ? 'text-brand-200' : 'text-brand-500'} />
                        <span className="text-xs font-semibold tracking-wide uppercase">Audio Command</span>
                     </div>
                   )
                 ))}
               </div>
             )}

             <MarkdownRenderer content={message.content} role={message.role} />

             {message.isStreaming && (
                 <span className="inline-block w-2 h-5 ml-1 bg-brand-400 animate-pulse align-middle rounded-full"></span>
             )}

             {/* Grounding Sources */}
             {!isUser && message.sources && message.sources.length > 0 && (
               <div className="mt-4 pt-3 border-t border-slate-100">
                  <div className="flex items-center gap-1.5 mb-2 text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                    <Globe size={12} /> Search Results
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {message.sources.map((src, idx) => (
                      <a 
                        key={idx}
                        href={src.url}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex items-center gap-1.5 px-2 py-1 bg-slate-50 border border-slate-200 rounded-md text-[10px] font-medium text-brand-700 hover:bg-brand-50 hover:border-brand-200 transition-colors"
                      >
                        <span className="truncate max-w-[150px]">{src.title || 'Source'}</span>
                        <ExternalLink size={10} />
                      </a>
                    ))}
                  </div>
               </div>
             )}

             {/* TTS Action */}
             {!isUser && message.content && !message.isStreaming && (
                <button 
                  onClick={handleToggleVoice}
                  className={`mt-3 flex items-center gap-2 text-[10px] font-bold uppercase tracking-widest transition-all px-3 py-1.5 rounded-lg border shadow-sm ${
                    localIsSpeaking 
                      ? 'bg-red-50 text-red-600 border-red-200' 
                      : 'bg-slate-50 text-slate-500 border-slate-200 hover:text-brand-600 hover:border-brand-200'
                  }`}
                >
                  {localIsSpeaking ? (
                    <><Square size={12} fill="currentColor" /> Stop Speaking</>
                  ) : (
                    <><Volume2 size={12} /> Listen</>
                  )}
                </button>
             )}
          </div>

          <span className="text-[10px] text-slate-400 mt-1.5 px-1 font-medium tracking-tight">
            {isUser ? 'USER' : "IBRAHIM'S AI"} • {new Date(message.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
          </span>
        </div>
      </div>
    </div>
  );
};

export default MessageBubble;

import React, { useState, useRef, useEffect } from 'react';
import { Send, StopCircle, Image as ImageIcon, Mic, X, Music, MicOff, Settings2, Radio } from 'lucide-react';
import { Attachment } from '../types';

interface InputAreaProps {
  onSend: (message: string, attachments: Attachment[]) => void;
  isLoading: boolean;
}

const InputArea: React.FC<InputAreaProps> = ({ onSend, isLoading }) => {
  const [input, setInput] = useState('');
  const [attachments, setAttachments] = useState<Attachment[]>([]);
  const [isRecording, setIsRecording] = useState(false);
  const [autoSend, setAutoSend] = useState(true);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Refocus the textarea when loading finishes or when recording stops
  useEffect(() => {
    if (!isLoading && !isRecording) {
      textareaRef.current?.focus();
    }
  }, [isLoading, isRecording]);

  const handleSubmit = (e?: React.FormEvent) => {
    e?.preventDefault();
    if ((input.trim() || attachments.length > 0) && !isLoading && !isRecording) {
      onSend(input.trim(), attachments);
      setInput('');
      setAttachments([]);
      if (textareaRef.current) {
        textareaRef.current.style.height = 'auto';
        textareaRef.current.focus();
      }
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit();
    }
  };

  const toggleRecording = async () => {
    if (isRecording) {
      stopRecording();
    } else {
      await startRecording();
    }
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mimeType = MediaRecorder.isTypeSupported('audio/webm;codecs=opus') 
        ? 'audio/webm;codecs=opus' 
        : 'audio/webm';

      const mediaRecorder = new MediaRecorder(stream, { mimeType });
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];

      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) audioChunksRef.current.push(event.data);
      };

      mediaRecorder.onstop = async () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: mimeType });
        const reader = new FileReader();
        reader.readAsDataURL(audioBlob);
        reader.onloadend = () => {
          const base64data = reader.result as string;
          const base64Content = base64data.split(',')[1];
          const newAttachment: Attachment = {
            type: 'audio',
            data: base64Content,
            mimeType: mimeType.split(';')[0],
            url: URL.createObjectURL(audioBlob)
          };

          if (autoSend) {
            onSend(input.trim(), [...attachments, newAttachment]);
            setInput('');
            setAttachments([]);
          } else {
            setAttachments(prev => [...prev, newAttachment]);
          }

          // Re-focus after auto-send logic completes
          setTimeout(() => textareaRef.current?.focus(), 100);
        };
        stream.getTracks().forEach(track => track.stop());
      };

      mediaRecorder.start();
      setIsRecording(true);
    } catch (err) {
      console.error("Microphone access denied:", err);
      alert("Could not access microphone.");
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;

    Array.from(files).forEach((file: File) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64data = reader.result as string;
        const base64Content = base64data.split(',')[1];
        setAttachments(prev => [...prev, {
          type: 'image',
          data: base64Content,
          mimeType: file.type,
          url: URL.createObjectURL(file)
        }]);
      };
      reader.readAsDataURL(file);
    });
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const removeAttachment = (index: number) => {
    setAttachments(prev => prev.filter((_, i) => i !== index));
  };

  return (
    <div className="flex-none bg-white border-t border-slate-200 p-4 pb-6 md:pb-4 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)]">
      <div className="max-w-4xl mx-auto">
        {attachments.length > 0 && (
          <div className="flex flex-wrap gap-3 mb-4">
            {attachments.map((att, i) => (
              <div key={i} className="relative group animate-in fade-in slide-in-from-bottom-2 duration-300">
                {att.type === 'image' ? (
                  <img src={att.url} className="w-16 h-16 object-cover rounded-xl border-2 border-brand-100 shadow-sm" alt="Preview" />
                ) : (
                  <div className="w-16 h-16 flex flex-col items-center justify-center bg-brand-50 rounded-xl border-2 border-brand-100 shadow-sm">
                    <Music className="text-brand-500" size={20} />
                    <span className="text-[8px] mt-1 font-black text-brand-600 uppercase tracking-tighter">Audio</span>
                  </div>
                )}
                <button 
                  onClick={() => removeAttachment(i)}
                  className="absolute -top-2 -right-2 bg-slate-900 text-white rounded-full p-1 shadow-lg ring-2 ring-white hover:bg-red-500 transition-colors"
                >
                  <X size={10} strokeWidth={3} />
                </button>
              </div>
            ))}
          </div>
        )}

        <form onSubmit={handleSubmit} className="flex items-end gap-3">
          <div className="flex-1 relative flex flex-col bg-slate-50 border border-slate-200 rounded-2xl p-2 focus-within:ring-2 focus-within:ring-brand-200 focus-within:border-brand-400 focus-within:bg-white transition-all shadow-sm">
            <textarea
              ref={textareaRef}
              rows={1}
              value={input}
              onChange={(e) => {
                setInput(e.target.value);
                e.target.style.height = 'auto';
                e.target.style.height = `${Math.min(e.target.scrollHeight, 200)}px`;
              }}
              onKeyDown={handleKeyDown}
              placeholder={isRecording ? "Listening to your command..." : "Ask Ibrahim's AI..."}
              className="w-full bg-transparent border-none focus:ring-0 text-slate-800 placeholder-slate-400 resize-none py-2 px-3 min-h-[44px] text-base disabled:opacity-50"
              disabled={isRecording}
            />
            <div className="flex items-center justify-between px-2 pt-1 border-t border-slate-100 mt-1">
              <div className="flex items-center gap-1">
                <button
                  type="button"
                  disabled={isRecording}
                  onClick={() => fileInputRef.current?.click()}
                  className="p-2 text-slate-500 hover:text-brand-600 hover:bg-brand-50 rounded-xl transition-all disabled:opacity-30"
                  title="Upload image"
                >
                  <ImageIcon size={18} />
                </button>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={handleImageUpload} />

                <button
                  type="button"
                  disabled={isLoading}
                  onClick={toggleRecording}
                  className={`p-2 rounded-xl transition-all disabled:opacity-30 ${
                    isRecording 
                      ? 'text-red-600 bg-red-50 ring-2 ring-red-200 animate-pulse' 
                      : 'text-slate-500 hover:text-brand-600 hover:bg-brand-50'
                  }`}
                  title={isRecording ? "Stop recording" : "Record voice command"}
                >
                  {isRecording ? <MicOff size={18} /> : <Mic size={18} />}
                </button>

                <div className="h-4 w-px bg-slate-200 mx-1" />

                <button
                  type="button"
                  onClick={() => setAutoSend(!autoSend)}
                  className={`flex items-center gap-1.5 px-2 py-1 rounded-lg text-[10px] font-bold uppercase transition-all ${
                    autoSend ? 'bg-brand-100 text-brand-700' : 'bg-slate-100 text-slate-500'
                  }`}
                  title="Auto-send after recording"
                >
                  <Radio size={12} className={autoSend ? 'animate-pulse' : ''} />
                  <span>{autoSend ? 'Auto-Send On' : 'Auto-Send Off'}</span>
                </button>
              </div>
              <div className="text-[9px] font-bold text-slate-400 tracking-widest uppercase flex items-center gap-1">
                Voice Assist <Settings2 size={10} />
              </div>
            </div>
          </div>
          <button
            type="submit"
            disabled={(!input.trim() && attachments.length === 0) || isLoading || isRecording}
            className={`p-4 rounded-2xl flex-none transition-all duration-300 shadow-sm active:scale-95 ${
              (!input.trim() && attachments.length === 0) || isLoading || isRecording
                ? 'bg-slate-200 text-slate-400 cursor-not-allowed'
                : 'bg-brand-600 text-white hover:bg-brand-700 hover:shadow-lg'
            }`}
          >
            {isLoading ? <StopCircle size={24} className="animate-spin-slow opacity-70" /> : <Send size={24} />}
          </button>
        </form>
      </div>
    </div>
  );
};

export default InputArea;

