import React, { useState, useRef, useEffect } from 'react';
import { Send, StopCircle, Image as ImageIcon, Mic, X, Music, MicOff, Settings2, Sparkles } from 'lucide-react';
import { Attachment } from '../types';

interface InputAreaProps {
  onSend: (message: string, attachments: Attachment[]) => void;
  isLoading: boolean;
}

const InputArea: React.FC<InputAreaProps> = ({ onSend, isLoading }) => {
  const [input, setInput] = useState('');
  const [attachments, setAttachments] = useState<Attachment[]>([]);
  const [isRecording, setIsRecording] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!isRecording) {
      textareaRef.current?.focus();
    }
  }, [isRecording]);

  const handleSubmit = (e?: React.FormEvent) => {
    e?.preventDefault();
    if ((input.trim() || attachments.length > 0) && !isLoading && !isRecording) {
      onSend(input.trim(), attachments);
      setInput('');
      setAttachments([]);
      if (textareaRef.current) {
        textareaRef.current.style.height = 'auto';
        textareaRef.current.focus();
      }
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSubmit();
    }
  };

  const toggleRecording = async () => {
    if (isRecording) {
      stopRecording();
    } else {
      await startRecording();
    }
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mimeType = MediaRecorder.isTypeSupported('audio/webm;codecs=opus') 
        ? 'audio/webm;codecs=opus' 
        : 'audio/webm';

      const mediaRecorder = new MediaRecorder(stream, { mimeType });
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];

      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) audioChunksRef.current.push(event.data);
      };

      mediaRecorder.onstop = async () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: mimeType });
        const reader = new FileReader();
        reader.readAsDataURL(audioBlob);
        reader.onloadend = () => {
          const base64data = reader.result as string;
          const base64Content = base64data.split(',')[1];
          const newAttachment: Attachment = {
            type: 'audio',
            data: base64Content,
            mimeType: mimeType.split(';')[0],
            url: URL.createObjectURL(audioBlob)
          };

          // Simplified: Always auto-send voice commands
          onSend(input.trim(), [...attachments, newAttachment]);
          setInput('');
          setAttachments([]);

          setTimeout(() => textareaRef.current?.focus(), 50);
        };
        stream.getTracks().forEach(track => track.stop());
      };

      mediaRecorder.start();
      setIsRecording(true);
    } catch (err) {
      console.error("Microphone access denied:", err);
      alert("Could not access microphone.");
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;

    Array.from(files).forEach((file: File) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64data = reader.result as string;
        const base64Content = base64data.split(',')[1];
        setAttachments(prev => [...prev, {
          type: 'image',
          data: base64Content,
          mimeType: file.type,
          url: URL.createObjectURL(file)
        }]);
      };
      reader.readAsDataURL(file);
    });
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const removeAttachment = (index: number) => {
    setAttachments(prev => prev.filter((_, i) => i !== index));
  };

  return (
    <div className="flex-none bg-white border-t border-slate-200 p-4 pb-6 md:pb-4 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)]">
      <div className="max-w-4xl mx-auto">
        {attachments.length > 0 && (
          <div className="flex flex-wrap gap-3 mb-4">
            {attachments.map((att, i) => (
              <div key={i} className="relative group animate-in fade-in slide-in-from-bottom-2 duration-300">
                {att.type === 'image' ? (
                  <img src={att.url} className="w-16 h-16 object-cover rounded-xl border-2 border-brand-100 shadow-sm" alt="Preview" />
                ) : (
                  <div className="w-16 h-16 flex flex-col items-center justify-center bg-brand-50 rounded-xl border-2 border-brand-100 shadow-sm">
                    <Music className="text-brand-500" size={20} />
                    <span className="text-[8px] mt-1 font-black text-brand-600 uppercase tracking-tighter">Audio</span>
                  </div>
                )}
                <button 
                  onClick={() => removeAttachment(i)}
                  className="absolute -top-2 -right-2 bg-slate-900 text-white rounded-full p-1 shadow-lg ring-2 ring-white hover:bg-red-500 transition-colors"
                >
                  <X size={10} strokeWidth={3} />
                </button>
              </div>
            ))}
          </div>
        )}

        <form onSubmit={handleSubmit} className="flex items-end gap-3">
          <div className="flex-1 relative flex flex-col bg-slate-50 border border-slate-200 rounded-2xl p-2 focus-within:ring-2 focus-within:ring-brand-200 focus-within:border-brand-400 focus-within:bg-white transition-all shadow-sm">
            <textarea
              ref={textareaRef}
              rows={1}
              value={input}
              onChange={(e) => {
                setInput(e.target.value);
                e.target.style.height = 'auto';
                e.target.style.height = `${Math.min(e.target.scrollHeight, 200)}px`;
              }}
              onKeyDown={handleKeyDown}
              placeholder={isRecording ? "Listening to your command..." : "Ask Ibrahim's AI..."}
              className={`w-full bg-transparent border-none focus:ring-0 text-slate-800 placeholder-slate-400 resize-none py-2 px-3 min-h-[44px] text-base transition-opacity ${isRecording ? 'opacity-50' : 'opacity-100'}`}
              disabled={isRecording}
            />

            {isRecording && (
              <div className="absolute inset-0 bg-brand-50/80 backdrop-blur-sm flex items-center justify-center rounded-2xl z-10 animate-in fade-in duration-200">
                <div className="flex items-center gap-3 text-brand-700 font-bold text-sm">
                  <div className="flex gap-1">
                    <div className="w-1.5 h-4 bg-brand-400 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                    <div className="w-1.5 h-6 bg-brand-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                    <div className="w-1.5 h-4 bg-brand-400 rounded-full animate-bounce"></div>
                  </div>
                  Listening...
                </div>
              </div>
            )}

            <div className="flex items-center justify-between px-2 pt-1 border-t border-slate-100 mt-1">
              <div className="flex items-center gap-1">
                <button
                  type="button"
                  disabled={isRecording}
                  onClick={() => fileInputRef.current?.click()}
                  className="p-2 text-slate-500 hover:text-brand-600 hover:bg-brand-50 rounded-xl transition-all disabled:opacity-30"
                  title="Upload image"
                >
                  <ImageIcon size={18} />
                </button>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={handleImageUpload} />

                <button
                  type="button"
                  disabled={isLoading}
                  onClick={toggleRecording}
                  className={`p-2 rounded-xl transition-all disabled:opacity-30 ${
                    isRecording 
                      ? 'text-red-600 bg-red-100 ring-2 ring-red-200' 
                      : 'text-slate-500 hover:text-brand-600 hover:bg-brand-50'
                  }`}
                  title={isRecording ? "Stop recording" : "Speak to Ibrahim"}
                >
                  {isRecording ? <MicOff size={18} /> : <Mic size={18} />}
                </button>
              </div>
              <div className="text-[9px] font-bold text-slate-400 tracking-widest uppercase flex items-center gap-1">
                Voice Assistant <Sparkles size={10} className="text-brand-400" />
              </div>
            </div>
          </div>
          <button
            type="submit"
            disabled={(!input.trim() && attachments.length === 0) || isLoading || isRecording}
            className={`p-4 rounded-2xl flex-none transition-all duration-300 shadow-sm active:scale-95 ${
              (!input.trim() && attachments.length === 0) || isLoading || isRecording
                ? 'bg-slate-200 text-slate-400 cursor-not-allowed'
                : 'bg-brand-600 text-white hover:bg-brand-700 hover:shadow-lg'
            }`}
          >
            {isLoading ? <StopCircle size={24} className="animate-spin-slow opacity-70" /> : <Send size={24} />}
          </button>
        </form>
      </div>
    </div>
  );
};

export default InputArea;

import { generateSpeech } from './geminiService';

let audioCtx: AudioContext | null = null;
let currentSource: AudioBufferSourceNode | null = null;
let currentBuffer: AudioBuffer | null = null;
let currentMessageId: string | null = null;

let startTime = 0; // When the source was started
let offset = 0;    // How much has already been played
let isPlaying = false;

const getAudioCtx = () => {
  if (!audioCtx) {
    audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
  }
  return audioCtx;
};

export const playAssistantVoice = async (text: string, messageId: string): Promise<void> => {
  const ctx = getAudioCtx();

  // If we are playing/paused on a DIFFERENT message, stop everything first
  if (currentMessageId !== messageId) {
    stopAssistantVoice();
    currentMessageId = messageId;
    try {
      currentBuffer = await generateSpeech(text);
    } catch (err) {
      console.error("Failed to generate speech:", err);
      return;
    }
  }

  // If already playing this message, do nothing
  if (isPlaying) return;

  // Start/Resume playback
  currentSource = ctx.createBufferSource();
  currentSource.buffer = currentBuffer;
  currentSource.connect(ctx.destination);

  currentSource.onended = () => {
    // Only clean up if it ended naturally (not stopped by pause/stop)
    if (isPlaying && currentSource) {
      const elapsedSinceStart = ctx.currentTime - startTime;
      if (offset + elapsedSinceStart >= (currentBuffer?.duration || 0)) {
        stopAssistantVoice();
      }
    }
  };

  startTime = ctx.currentTime;
  currentSource.start(0, offset);
  isPlaying = true;
};

export const pauseAssistantVoice = () => {
  const ctx = getAudioCtx();
  if (!isPlaying || !currentSource) return;

  // Calculate where we are
  offset += (ctx.currentTime - startTime);

  // Stop the source (it's "start-once")
  try {
    currentSource.stop();
  } catch (e) {}

  currentSource = null;
  isPlaying = false;
};

export const stopAssistantVoice = () => {
  if (currentSource) {
    try {
      currentSource.stop();
    } catch (e) {}
    currentSource = null;
  }
  currentBuffer = null;
  currentMessageId = null;
  offset = 0;
  startTime = 0;
  isPlaying = false;
};

export const getPlaybackStatus = (messageId: string) => {
  if (currentMessageId !== messageId) return 'idle';
  return isPlaying ? 'playing' : 'paused';
};

export const isSpeaking = () => isPlaying;

import React, { useState, useEffect } from 'react';
import { Message, Role, MessageMood } from '../types';
import { Bot, User, Music, Volume2, Globe, Heart, Zap, Shield, Brain, Sparkles, Smile, Search, HelpCircle, Square, Play, Pause } from 'lucide-react';
import MarkdownRenderer from './MarkdownRenderer';
import { playAssistantVoice, pauseAssistantVoice, stopAssistantVoice, getPlaybackStatus } from '../services/audioService';

interface MessageBubbleProps {
  message: Message;
}

const moodConfig: Record<MessageMood, { icon: React.ReactNode, color: string, bg: string }> = {
  Thoughtful: { icon: <Brain size={10} />, color: 'text-purple-600', bg: 'bg-purple-50 border-purple-100' },
  Empathetic: { icon: <Heart size={10} />, color: 'text-rose-600', bg: 'bg-rose-50 border-rose-100' },
  Inspired: { icon: <Zap size={10} />, color: 'text-amber-600', bg: 'bg-amber-50 border-amber-100' },
  Calm: { icon: <Sparkles size={10} />, color: 'text-blue-600', bg: 'bg-blue-50 border-blue-100' },
  Cheerful: { icon: <Smile size={10} />, color: 'text-green-600', bg: 'bg-green-50 border-green-100' },
  Protective: { icon: <Shield size={10} />, color: 'text-orange-600', bg: 'bg-orange-50 border-orange-100' },
  Curious: { icon: <HelpCircle size={10} />, color: 'text-indigo-600', bg: 'bg-indigo-50 border-indigo-100' },
  Analytical: { icon: <Search size={10} />, color: 'text-slate-600', bg: 'bg-slate-50 border-slate-100' },
};

const MessageBubble: React.FC<MessageBubbleProps> = ({ message }) => {
  const isUser = message.role === Role.USER;
  const [playbackState, setPlaybackState] = useState<'idle' | 'playing' | 'paused'>('idle');
  const mood = message.mood && moodConfig[message.mood] ? moodConfig[message.mood] : moodConfig['Calm'];

  useEffect(() => {
    const interval = setInterval(() => {
      const current = getPlaybackStatus(message.id);
      if (current !== playbackState) {
        setPlaybackState(current);
      }
    }, 100);
    return () => clearInterval(interval);
  }, [playbackState, message.id]);

  const handlePlay = async () => {
    if (playbackState === 'playing') {
      pauseAssistantVoice();
    } else {
      if (!message.content) return;
      await playAssistantVoice(message.content, message.id);
    }
  };

  const handleStop = (e: React.MouseEvent) => {
    e.stopPropagation();
    stopAssistantVoice();
  };

  return (
    <div className={`flex w-full mb-6 animate-fade-in ${isUser ? 'justify-end' : 'justify-start'}`}>
      <div className={`flex max-w-[95%] md:max-w-[85%] gap-3 ${isUser ? 'flex-row-reverse' : 'flex-row'}`}>

        {/* Avatar */}
        <div className="flex-none pt-1">
          <div className={`w-9 h-9 rounded-xl flex items-center justify-center shadow-md transition-all duration-500 ${
            isUser ? 'bg-brand-600 text-white' : 'bg-white border border-slate-200 text-brand-600'
          } ${(!isUser && message.isStreaming) || playbackState === 'playing' ? 'animate-pulse ring-2 ring-brand-400' : ''}`}>
            {isUser ? <User size={18} /> : <Bot size={20} />}
          </div>
        </div>

        {/* Message Content */}
        <div className={`flex flex-col ${isUser ? 'items-end' : 'items-start'}`}>
          {/* AI Mood Badge */}
          {!isUser && message.mood && (
            <div className={`flex items-center gap-1 px-2 py-0.5 rounded-full border mb-1 transition-all animate-fade-in ${mood.bg} ${mood.color}`}>
              {mood.icon}
              <span className="text-[9px] font-bold uppercase tracking-wider">{message.mood}</span>
            </div>
          )}

          <div className={`relative px-5 py-4 rounded-2xl shadow-sm transition-all duration-200 ${
            isUser 
              ? 'bg-brand-600 text-white rounded-tr-sm' 
              : 'bg-white border border-slate-100 text-slate-800 rounded-tl-sm'
          }`}>
             {/* Attachments Rendering */}
             {message.attachments && message.attachments.length > 0 && (
               <div className="flex flex-col gap-3 mb-4">
                 {message.attachments.map((att, i) => (
                   att.type === 'image' ? (
                     <div key={i} className="relative group overflow-hidden rounded-xl border border-slate-200/50 bg-slate-50">
                        <img 
                          src={att.url || att.data} 
                          className="max-w-full max-h-[500px] object-contain mx-auto" 
                          alt="Generated or attached" 
                        />
                     </div>
                   ) : (
                     <div key={i} className={`flex items-center gap-3 px-4 py-3 rounded-xl border ${isUser ? 'bg-brand-700 border-brand-500' : 'bg-slate-50 border-slate-200'}`}>
                        <Music size={16} className={isUser ? 'text-brand-200' : 'text-brand-500'} />
                        <span className="text-xs font-semibold tracking-wide uppercase">Audio Command</span>
                     </div>
                   )
                 ))}
               </div>
             )}

             <MarkdownRenderer content={message.content} role={message.role} />

             {message.isStreaming && (
                 <span className="inline-block w-2 h-5 ml-1 bg-brand-400 animate-pulse align-middle rounded-full"></span>
             )}

             {/* Grounding Sources */}
             {!isUser && message.sources && message.sources.length > 0 && (
               <div className="mt-4 pt-3 border-t border-slate-100">
                  <div className="flex items-center gap-1.5 mb-2 text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                    <Globe size={12} /> Search Results
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {message.sources.map((src, idx) => (
                      <a 
                        key={idx}
                        href={src.url}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex items-center gap-1.5 px-2 py-1 bg-slate-50 border border-slate-200 rounded-md text-[10px] font-medium text-brand-700 hover:bg-brand-50 hover:border-brand-200 transition-colors"
                      >
                        <span className="truncate max-w-[150px]">{src.title || 'Source'}</span>
                        <ExternalLink size={10} />
                      </a>
                    ))}
                  </div>
               </div>
             )}

             {/* Listen Bar (Media Controls) */}
             {!isUser && message.content && !message.isStreaming && (
                <div className="mt-4 flex items-center gap-1">
                  <div className={`flex items-center gap-1 p-1 rounded-xl border transition-all duration-300 ${
                    playbackState !== 'idle' 
                      ? 'bg-brand-50 border-brand-200 shadow-sm' 
                      : 'bg-slate-50 border-slate-200 hover:border-slate-300'
                  }`}>
                    <button 
                      onClick={handlePlay}
                      className={`p-1.5 rounded-lg transition-all ${
                        playbackState === 'playing'
                          ? 'bg-brand-600 text-white'
                          : 'text-slate-500 hover:bg-white hover:text-brand-600'
                      }`}
                      title={playbackState === 'playing' ? "Pause" : "Play"}
                    >
                      {playbackState === 'playing' ? <Pause size={14} fill="currentColor" /> : <Play size={14} fill="currentColor" />}
                    </button>

                    {playbackState !== 'idle' && (
                      <>
                        <div className="h-4 w-px bg-brand-200 mx-0.5" />
                        <button 
                          onClick={handleStop}
                          className="p-1.5 rounded-lg text-slate-400 hover:text-red-500 hover:bg-white transition-all"
                          title="Stop"
                        >
                          <Square size={14} fill="currentColor" />
                        </button>
                        <div className="px-2 py-1 flex items-center gap-2">
                          <div className="flex gap-0.5 items-end h-3">
                            {[0.4, 0.7, 1, 0.6, 0.9, 0.5].map((h, i) => (
                              <div 
                                key={i} 
                                className={`w-0.5 bg-brand-400 rounded-full transition-all duration-300 ${playbackState === 'playing' ? 'animate-pulse' : 'opacity-30'}`}
                                style={{ 
                                  height: `${h * 100}%`,
                                  animationDelay: `${i * 0.1}s` 
                                }}
                              />
                            ))}
                          </div>
                          <span className="text-[9px] font-bold text-brand-600 uppercase tracking-tight">
                            {playbackState === 'playing' ? 'Listening' : 'Paused'}
                          </span>
                        </div>
                      </>
                    )}

                    {playbackState === 'idle' && (
                      <button 
                        onClick={handlePlay}
                        className="pr-3 pl-1 py-1 text-[10px] font-bold text-slate-500 uppercase tracking-widest hover:text-brand-600 transition-colors"
                      >
                        Listen
                      </button>
                    )}
                  </div>
                </div>
             )}
          </div>

          <span className="text-[10px] text-slate-400 mt-1.5 px-1 font-medium tracking-tight">
            {isUser ? 'USER' : "IBRAHIM'S AI"} • {new Date(message.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
          </span>
        </div>
      </div>
    </div>
  );
};

export default MessageBubble;

import React, { useState, useCallback } from 'react';
import Header from './components/Header';
import ChatInterface from './components/ChatInterface';
import InputArea from './components/InputArea';
import { Message, Role, Attachment, GroundingSource, MessageMood } from './types';
import { streamChatResponse } from './services/geminiService';
import { playAssistantVoice } from './services/audioService';
import { v4 as uuidv4 } from 'uuid';

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isVoiceMode, setIsVoiceMode] = useState(false);

  const handleSendMessage = useCallback(async (content: string, attachments: Attachment[]) => {
    if (!content.trim() && attachments.length === 0) return;

    const hasAudioInput = attachments.some(a => a.type === 'audio');

    const userMessage: Message = {
      id: uuidv4(),
      role: Role.USER,
      content,
      attachments,
      timestamp: Date.now(),
    };

    setMessages((prev) => [...prev, userMessage]);
    setIsLoading(true);

    try {
      const aiMessageId = uuidv4();
      const initialAiMessage: Message = {
        id: aiMessageId,
        role: Role.MODEL,
        content: '',
        attachments: [],
        sources: [],
        isStreaming: true,
        timestamp: Date.now(),
      };

      setMessages((prev) => [...prev, initialAiMessage]);

      const seenImageUrls = new Set<string>();
      const seenSourceUrls = new Set<string>();
      let finalAiContent = '';

      await streamChatResponse(
        messages, 
        content,
        attachments,
        (text, imageUrl, sources, mood) => {
          setMessages((prev) => 
            prev.map((msg) => {
              if (msg.id === aiMessageId) {
                let updatedMsg = { ...msg };

                if (text) {
                  updatedMsg.content = text;
                  finalAiContent = text;
                }

                if (mood) {
                  updatedMsg.mood = mood;
                }

                if (imageUrl && !seenImageUrls.has(imageUrl)) {
                  seenImageUrls.add(imageUrl);
                  updatedMsg.attachments = [
                    ...(updatedMsg.attachments || []),
                    {
                      type: 'image',
                      data: imageUrl,
                      mimeType: 'image/png'
                    }
                  ];
                }

                if (sources) {
                  const newSources = [...(updatedMsg.sources || [])];
                  sources.forEach(src => {
                    if (!seenSourceUrls.has(src.url)) {
                      seenSourceUrls.add(src.url);
                      newSources.push(src);
                    }
                  });
                  updatedMsg.sources = newSources;
                }

                return updatedMsg;
              }
              return msg;
            })
          );
        }
      );

      setMessages((prev) => 
        prev.map((msg) => 
          msg.id === aiMessageId 
            ? { ...msg, isStreaming: false } 
            : msg
        )
      );

      // Auto-respond with voice if Voice Mode is ON OR the user used audio input
      if ((isVoiceMode || hasAudioInput) && finalAiContent) {
        playAssistantVoice(finalAiContent, aiMessageId);
      }

    } catch (error: any) {
      console.error("Error sending message:", error);
      const errorStr = JSON.stringify(error);

      if (errorStr.includes("Requested entity was not found") || 
          errorStr.includes("PERMISSION_DENIED") || 
          error?.status === 403 || 
          error?.code === 403) {

        const aistudio = (window as any).aistudio;
        if (aistudio) {
          aistudio.openSelectKey();
        }
      }

       const errorMessage: Message = {
        id: uuidv4(),
        role: Role.MODEL,
        content: "I apologize, but I encountered an error. Please ensure you have selected a valid paid API key for search features.",
        timestamp: Date.now(),
      };
      setMessages(prev => [...prev.filter(m => !m.isStreaming), errorMessage]);
    } finally {
      setIsLoading(false);
    }
  }, [messages, isVoiceMode]);

  return (
    <div className="flex flex-col h-screen bg-slate-50 text-slate-900 font-sans">
      <Header 
        isVoiceMode={isVoiceMode} 
        onToggleVoiceMode={() => setIsVoiceMode(!isVoiceMode)} 
      />
      <main className="flex-1 flex flex-col min-h-0 relative">
        <ChatInterface messages={messages} isLoading={isLoading} />
        <InputArea onSend={handleSendMessage} isLoading={isLoading} />
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Message, Role, MessageMood } from '../types';
import { Bot, User, Music, Volume2, Globe, Heart, Zap, Shield, Brain, Sparkles, Smile, Search, HelpCircle, Square, Play, Pause, ExternalLink } from 'lucide-react';
import MarkdownRenderer from './MarkdownRenderer';
import { playAssistantVoice, pauseAssistantVoice, stopAssistantVoice, getPlaybackStatus } from '../services/audioService';

interface MessageBubbleProps {
  message: Message;
}

const moodConfig: Record<MessageMood, { icon: React.ReactNode, color: string, bg: string }> = {
  Thoughtful: { icon: <Brain size={10} />, color: 'text-purple-600', bg: 'bg-purple-50 border-purple-100' },
  Empathetic: { icon: <Heart size={10} />, color: 'text-rose-600', bg: 'bg-rose-50 border-rose-100' },
  Inspired: { icon: <Zap size={10} />, color: 'text-amber-600', bg: 'bg-amber-50 border-amber-100' },
  Calm: { icon: <Sparkles size={10} />, color: 'text-blue-600', bg: 'bg-blue-50 border-blue-100' },
  Cheerful: { icon: <Smile size={10} />, color: 'text-green-600', bg: 'bg-green-50 border-green-100' },
  Protective: { icon: <Shield size={10} />, color: 'text-orange-600', bg: 'bg-orange-50 border-orange-100' },
  Curious: { icon: <HelpCircle size={10} />, color: 'text-indigo-600', bg: 'bg-indigo-50 border-indigo-100' },
  Analytical: { icon: <Search size={10} />, color: 'text-slate-600', bg: 'bg-slate-50 border-slate-100' },
};

const MessageBubble: React.FC<MessageBubbleProps> = ({ message }) => {
  const isUser = message.role === Role.USER;
  const [playbackState, setPlaybackState] = useState<'idle' | 'playing' | 'paused'>('idle');
  const mood = message.mood && moodConfig[message.mood] ? moodConfig[message.mood] : moodConfig['Calm'];

  useEffect(() => {
    const interval = setInterval(() => {
      const current = getPlaybackStatus(message.id);
      if (current !== playbackState) {
        setPlaybackState(current);
      }
    }, 100);
    return () => clearInterval(interval);
  }, [playbackState, message.id]);

  const handlePlay = async () => {
    if (playbackState === 'playing') {
      pauseAssistantVoice();
    } else {
      if (!message.content) return;
      await playAssistantVoice(message.content, message.id);
    }
  };

  const handleStop = (e: React.MouseEvent) => {
    e.stopPropagation();
    stopAssistantVoice();
  };

  return (
    <div className={`flex w-full mb-6 animate-fade-in ${isUser ? 'justify-end' : 'justify-start'}`}>
      <div className={`flex max-w-[95%] md:max-w-[85%] gap-3 ${isUser ? 'flex-row-reverse' : 'flex-row'}`}>

        {/* Avatar */}
        <div className="flex-none pt-1">
          <div className={`w-9 h-9 rounded-xl flex items-center justify-center shadow-md transition-all duration-500 ${
            isUser ? 'bg-brand-600 text-white' : 'bg-white border border-slate-200 text-brand-600'
          } ${(!isUser && message.isStreaming) || playbackState === 'playing' ? 'animate-pulse ring-2 ring-brand-400' : ''}`}>
            {isUser ? <User size={18} /> : <Bot size={20} />}
          </div>
        </div>

        {/* Message Content */}
        <div className={`flex flex-col ${isUser ? 'items-end' : 'items-start'}`}>
          {/* AI Mood Badge */}
          {!isUser && message.mood && (
            <div className={`flex items-center gap-1 px-2 py-0.5 rounded-full border mb-1 transition-all animate-fade-in ${mood.bg} ${mood.color}`}>
              {mood.icon}
              <span className="text-[9px] font-bold uppercase tracking-wider">{message.mood}</span>
            </div>
          )}

          <div className={`relative px-5 py-4 rounded-2xl shadow-sm transition-all duration-200 ${
            isUser 
              ? 'bg-brand-600 text-white rounded-tr-sm' 
              : 'bg-white border border-slate-100 text-slate-800 rounded-tl-sm'
          }`}>
             {/* Attachments Rendering */}
             {message.attachments && message.attachments.length > 0 && (
               <div className="flex flex-col gap-3 mb-4">
                 {message.attachments.map((att, i) => (
                   att.type === 'image' ? (
                     <div key={i} className="relative group overflow-hidden rounded-xl border border-slate-200/50 bg-slate-50">
                        <img 
                          src={att.url || att.data} 
                          className="max-w-full max-h-[500px] object-contain mx-auto" 
                          alt="Generated or attached" 
                        />
                     </div>
                   ) : (
                     <div key={i} className={`flex items-center gap-3 px-4 py-3 rounded-xl border ${isUser ? 'bg-brand-700 border-brand-500' : 'bg-slate-50 border-slate-200'}`}>
                        <Music size={16} className={isUser ? 'text-brand-200' : 'text-brand-500'} />
                        <span className="text-xs font-semibold tracking-wide uppercase">Audio Command</span>
                     </div>
                   )
                 ))}
               </div>
             )}

             <MarkdownRenderer content={message.content} role={message.role} />

             {message.isStreaming && (
                 <span className="inline-block w-2 h-5 ml-1 bg-brand-400 animate-pulse align-middle rounded-full"></span>
             )}

             {/* Grounding Sources */}
             {!isUser && message.sources && message.sources.length > 0 && (
               <div className="mt-4 pt-3 border-t border-slate-100">
                  <div className="flex items-center gap-1.5 mb-2 text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                    <Globe size={12} /> Search Results
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {message.sources.map((src, idx) => (
                      <a 
                        key={idx}
                        href={src.url}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex items-center gap-1.5 px-2 py-1 bg-slate-50 border border-slate-200 rounded-md text-[10px] font-medium text-brand-700 hover:bg-brand-50 hover:border-brand-200 transition-colors"
                      >
                        <span className="truncate max-w-[150px]">{src.title || 'Source'}</span>
                        <ExternalLink size={10} />
                      </a>
                    ))}
                  </div>
               </div>
             )}

             {/* Listen Bar (Media Controls) */}
             {!isUser && message.content && !message.isStreaming && (
                <div className="mt-4 flex items-center gap-1">
                  <div className={`flex items-center gap-1 p-1 rounded-xl border transition-all duration-300 ${
                    playbackState !== 'idle' 
                      ? 'bg-brand-50 border-brand-200 shadow-sm' 
                      : 'bg-slate-50 border-slate-200 hover:border-slate-300'
                  }`}>
                    <button 
                      onClick={handlePlay}
                      className={`p-1.5 rounded-lg transition-all ${
                        playbackState === 'playing'
                          ? 'bg-brand-600 text-white'
                          : 'text-slate-500 hover:bg-white hover:text-brand-600'
                      }`}
                      title={playbackState === 'playing' ? "Pause" : "Play"}
                    >
                      {playbackState === 'playing' ? <Pause size={14} fill="currentColor" /> : <Play size={14} fill="currentColor" />}
                    </button>

                    {playbackState !== 'idle' && (
                      <>
                        <div className="h-4 w-px bg-brand-200 mx-0.5" />
                        <button 
                          onClick={handleStop}
                          className="p-1.5 rounded-lg text-slate-400 hover:text-red-500 hover:bg-white transition-all"
                          title="Stop"
                        >
                          <Square size={14} fill="currentColor" />
                        </button>
                        <div className="px-2 py-1 flex items-center gap-2">
                          <div className="flex gap-0.5 items-end h-3">
                            {[0.4, 0.7, 1, 0.6, 0.9, 0.5].map((h, i) => (
                              <div 
                                key={i} 
                                className={`w-0.5 bg-brand-400 rounded-full transition-all duration-300 ${playbackState === 'playing' ? 'animate-pulse' : 'opacity-30'}`}
                                style={{ 
                                  height: `${h * 100}%`,
                                  animationDelay: `${i * 0.1}s` 
                                }}
                              />
                            ))}
                          </div>
                          <span className="text-[9px] font-bold text-brand-600 uppercase tracking-tight">
                            {playbackState === 'playing' ? 'Listening' : 'Paused'}
                          </span>
                        </div>
                      </>
                    )}

                    {playbackState === 'idle' && (
                      <button 
                        onClick={handlePlay}
                        className="pr-3 pl-1 py-1 text-[10px] font-bold text-slate-500 uppercase tracking-widest hover:text-brand-600 transition-colors"
                      >
                        Listen
                      </button>
                    )}
                  </div>
                </div>
             )}
          </div>

          <span className="text-[10px] text-slate-400 mt-1.5 px-1 font-medium tracking-tight">
            {isUser ? 'USER' : "IBRAHIM'S AI"} • {new Date(message.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
          </span>
        </div>
      </div>
    </div>
  );
};

export default MessageBubble;

import { GoogleGenAI, GenerateContentResponse, Chat, Modality } from "@google/genai";
import { Message, Role, Attachment, GroundingSource, MessageMood } from "../types";
import { IBRAHIM_SYSTEM_INSTRUCTION } from "../constants";

// Updated model to gemini-3-pro-image-preview to support complex reasoning, search grounding, and image generation.
const CORE_MODEL = 'gemini-3-pro-image-preview';
const TTS_MODEL = 'gemini-2.5-flash-preview-tts';

// AI client initialization using process.env.API_KEY.
const getAiClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const streamChatResponse = async (
  history: Message[],
  userMessage: string,
  attachments: Attachment[],
  onUpdate: (text: string, imageUrl?: string, sources?: GroundingSource[], mood?: MessageMood) => void
): Promise<void> => {
  const ai = getAiClient();

  try {
    const chatHistory = history.map((msg) => ({
      role: msg.role === Role.USER ? 'user' : 'model',
      parts: [
        { text: msg.mood ? `[MOOD:${msg.mood}] ${msg.content}` : msg.content },
        ...(msg.attachments?.map(att => ({
          inlineData: {
            data: att.data,
            mimeType: att.mimeType
          }
        })) || [])
      ],
    }));

    const currentDateTime = new Date().toLocaleString('en-US', {
      dateStyle: 'full',
      timeStyle: 'medium',
    });

    const systemInstructionWithContext = `${IBRAHIM_SYSTEM_INSTRUCTION}
\n[System Context]\nCurrent Date/Time: ${currentDateTime}
`;

    const chat: Chat = ai.chats.create({
      model: CORE_MODEL,
      history: chatHistory,
      config: {
        systemInstruction: systemInstructionWithContext,
        temperature: 0.8,
        // Using googleSearch tool as required for grounding.
        tools: [{ googleSearch: {} }],
      },
    });

    const currentParts: any[] = [];
    if (userMessage.trim()) currentParts.push({ text: userMessage });

    attachments.forEach(att => {
      currentParts.push({
        inlineData: {
          data: att.data,
          mimeType: att.mimeType
        }
      });
    });

    if (currentParts.length === 0) currentParts.push({ text: "Hello" });

    const result = await chat.sendMessageStream({ 
      message: currentParts
    });

    let fullText = "";
    let currentMood: MessageMood | undefined;

    for await (const chunk of result) {
      const c = chunk as GenerateContentResponse;

      const sources: GroundingSource[] = [];
      const chunks = c.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (chunks) {
        chunks.forEach((gc: any) => {
          if (gc.web) {
            sources.push({ title: gc.web.title, url: gc.web.uri });
          }
        });
      }

      if (c.candidates?.[0]?.content?.parts) {
        for (const part of c.candidates[0].content.parts) {
          if (part.text) {
            fullText += part.text;

            // Extract Mood Tag: [MOOD:MoodName]
            const moodMatch = fullText.match(/\[MOOD:(\w+)\]/);
            if (moodMatch && !currentMood) {
              currentMood = moodMatch[1] as MessageMood;
            }

            // Clean text for display by removing the mood tag
            const displayText = fullText.replace(/\[MOOD:\w+\]/, "").trim();
            onUpdate(displayText, undefined, sources.length > 0 ? sources : undefined, currentMood);
          }
          // Find the image part from the model response.
          if (part.inlineData && part.inlineData.mimeType.startsWith('image/')) {
            const imageUrl = `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
            onUpdate("", imageUrl);
          }
        }
      }
    }
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

export const generateSpeech = async (text: string): Promise<AudioBuffer> => {
  const ai = getAiClient();
  const response = await ai.models.generateContent({
    model: TTS_MODEL,
    contents: [{ parts: [{ text: `Speak this as Ibrahim's AI: ${text}` }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName: 'Kore' },
        },
      },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64Audio) throw new Error("No audio data returned");

  const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
  const audioData = decodeBase64(base64Audio);
  return await decodeAudioData(audioData, audioContext, 24000, 1);
};

// Manual base64 decoding implementation following coding guidelines.
function decodeBase64(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

// Raw PCM audio decoding implementation following coding guidelines.
async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState, useEffect } from 'react';
import { Sparkles, Globe, ShieldCheck, Settings, Volume2, VolumeX } from 'lucide-react';

interface HeaderProps {
  isVoiceMode: boolean;
  onToggleVoiceMode: () => void;
}

const Header: React.FC<HeaderProps> = ({ isVoiceMode, onToggleVoiceMode }) => {
  const [hasApiKey, setHasApiKey] = useState(false);

  useEffect(() => {
    const checkKey = async () => {
      const aistudio = (window as any).aistudio;
      if (aistudio) {
        try {
          const selected = await aistudio.hasSelectedApiKey();
          setHasApiKey(selected);
        } catch (err) {
          console.error("Error checking API key status:", err);
        }
      }
    };
    checkKey();
    const interval = setInterval(checkKey, 2000);
    return () => clearInterval(interval);
  }, []);

  const handleKeySelect = async () => {
    const aistudio = (window as any).aistudio;
    if (aistudio) {
      try {
        await aistudio.openSelectKey();
        setHasApiKey(true);
      } catch (err) {
        console.error("Error opening key selection dialog:", err);
      }
    }
  };

  return (
    <header className="flex-none bg-white border-b border-slate-200 px-4 py-3 shadow-sm z-10">
      <div className="max-w-4xl mx-auto flex items-center justify-between">
        <div className="flex items-center gap-2.5">
          <div className="bg-brand-500 p-2 rounded-lg text-white shadow-md shadow-brand-200">
            <Sparkles size={24} />
          </div>
          <div className="hidden sm:block">
            <h1 className="text-xl font-bold text-slate-900 tracking-tight leading-none mb-1">Ibrahim's AI</h1>
            <p className="text-[10px] text-slate-500 font-bold uppercase tracking-tighter flex items-center gap-1">
              Search Active <Globe size={10} className="text-brand-500" />
            </p>
          </div>
        </div>

        <div className="flex items-center gap-3">
            <button 
              onClick={onToggleVoiceMode}
              className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-bold transition-all border ${
                isVoiceMode 
                  ? 'bg-brand-600 text-white border-brand-600 shadow-sm' 
                  : 'bg-slate-50 text-slate-600 border-slate-200 hover:bg-slate-100'
              }`}
              title={isVoiceMode ? "Disable Auto-Voice" : "Enable Auto-Voice"}
            >
              {isVoiceMode ? <Volume2 size={14} /> : <VolumeX size={14} />}
              <span className="hidden xs:inline">Voice Mode {isVoiceMode ? 'ON' : 'OFF'}</span>
            </button>

            <div className="h-6 w-px bg-slate-200 hidden xs:block" />

            {!hasApiKey ? (
              <div className="flex flex-col items-end gap-1">
                <button 
                  onClick={handleKeySelect}
                  className="flex items-center gap-1.5 px-3 py-1.5 bg-brand-50 text-brand-700 border border-brand-200 rounded-full text-xs font-bold hover:bg-brand-100 transition-colors"
                >
                  <Settings size={14} /> <span className="hidden md:inline">Global Key</span>
                </button>
                <a 
                  href="https://ai.google.dev/gemini-api/docs/billing" 
                  target="_blank" 
                  rel="noopener noreferrer"
                  className="text-[9px] text-slate-400 hover:text-brand-600 transition-colors underline decoration-dotted underline-offset-2"
                >
                  Billing Setup
                </a>
              </div>
            ) : (
              <div className="flex items-center gap-1.5 px-3 py-1.5 bg-green-50 text-green-700 border border-green-200 rounded-full text-xs font-bold">
                <ShieldCheck size={14} /> <span className="hidden md:inline">Ready</span>
              </div>
            )}
        </div>
      </div>
    </header>
  );
};

export default Header;

